    out = [row[:] for row in grid]
    bg = grid[0][0]

    # A full vertical 2-line is a divider. Pack the non-background,
    # non-divider pattern against it, then mark its far edge with 8.
    div = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if div is None:
        return out

    cols = [c for c in range(w) if c != div and any(grid[r][c] not in (bg, 2) for r in range(h))]
    if not cols:
        return out

    left_side = max(cols) < div
    if left_side:
        edge = max(cols)
        # Shift the pattern rightward if there is empty space before the divider.
        shift = div - 1 - edge
        if shift > 0:
            for r in range(h):
                for c in range(w):
                    if grid[r][c] not in (bg, 2):
                        out[r][c] = bg
            for r in range(h):
                for c in range(w):
                    if grid[r][c] not in (bg, 2):
                        out[r][c + shift] = grid[r][c]
            edge += shift
        mark = edge - 1
    else:
        edge = min(cols)
        shift = edge - (div + 1)
        if shift > 0:
            for r in range(h):
                for c in range(w):
                    if grid[r][c] not in (bg, 2):
                        out[r][c] = bg
            for r in range(h):
                for c in range(w):
                    if grid[r][c] not in (bg, 2):
                        out[r][c - shift] = grid[r][c]
            edge -= shift
        mark = max(cols) + (div + 1 - min(cols)) - 1

    if 0 <= mark < w and mark != div:
        for r in range(h):
