    # Find the full-height divider.
    div = next((c for c in range(w) if all(grid[r][c] == 2 for r in range(h))), None)
    if div is None:
        return out

    # Mark the outside edge of the colored pattern on the side opposite
    # the divider.
    colored_cols = [
        c for c in range(w) if c != div
        and any(grid[r][c] not in (bg, 2) for r in range(h))
    ]
    if not colored_cols:
        return out

    if max(colored_cols) < div:
        mark = min(colored_cols) - 1
    else:
        mark = max(colored_cols) + 1

    if 0 <= mark < w:
        for r in range(h):
            out[r][mark] = 8
    return out
